function waikaText(key, locale = document.documentElement.lang) {
  return waikaCopy[key]?.[locale === "en" ? "en" : "es"] || key;
}

function addSharedControls() {
  if (document.querySelector("[data-site-ui]")) return;
  const shared = document.createElement("div");
  shared.dataset.siteUi = "true";
  shared.innerHTML = `
    <div class="site-dock" aria-label="Accesos rápidos">
      <button type="button" data-chat-open aria-expanded="false" aria-controls="waika-chat" aria-label="Abrir el asistente" title="Abrir el asistente"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.8 7.5 8.4 8.4 0 0 1-3.7-.9L4 19l1-4a7.3 7.3 0 0 1-.9-3.5A7.6 7.6 0 0 1 12 4a7.6 7.6 0 0 1 8 7.5Z"/><path d="M8.5 11.5h7M8.5 14.5h4"/></svg></button>
      <button type="button" data-language aria-label="Cambiar idioma" title="Cambiar idioma">EN</button>
      <button type="button" data-back-top aria-label="Volver arriba" title="Volver arriba"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 14 7-7 7 7M12 7v13"/></svg></button>
    </div>
    <section class="chat-panel" id="waika-chat" aria-labelledby="chat-title" aria-modal="false" hidden>
      <header class="chat-head"><strong id="chat-title">Asistente Waika</strong><button type="button" data-chat-close aria-label="Cerrar asistente">×</button></header>
      <div class="chat-messages" role="log" aria-live="polite" aria-relevant="additions text"><p class="chat-message" data-chat-intro></p></div>
      <form class="chat-form" data-chat-form><label class="sr-only" for="chat-input">Escribe tu pregunta</label><textarea id="chat-input" name="message" maxlength="1200" required></textarea><button type="submit">Enviar</button></form>
    </section>
    <aside class="cookie-banner" role="region" aria-labelledby="cookie-title" hidden>
      <p><strong id="cookie-title">Tu privacidad, primero.</strong><br><span data-cookie-message></span></p>
      <div class="cookie-actions"><button type="button" data-cookie-reject></button><button type="button" data-cookie-accept></button><button type="button" data-cookie-settings></button></div>
    </aside>
    <dialog class="cookie-dialog" aria-labelledby="cookie-dialog-title">
      <form method="dialog" data-cookie-form>
        <h2 id="cookie-dialog-title">Preferencias de privacidad</h2>
        <div class="cookie-setting"><div><strong data-cookie-necessary-label></strong><p data-cookie-necessary-help></p></div><input type="checkbox" checked disabled aria-label="Siempre activas"></div>
        <label class="cookie-setting"><div><strong data-cookie-analytics-label></strong><p data-cookie-analytics-help></p></div><input type="checkbox" name="analytics" data-cookie-analytics></label>
        <label class="cookie-setting"><div><strong data-cookie-marketing-label></strong><p data-cookie-marketing-help></p></div><input type="checkbox" name="marketing" data-cookie-marketing></label>
        <div class="cookie-dialog-actions"><button type="button" data-cookie-only-necessary></button><button type="button" data-cookie-cancel></button><button type="button" data-cookie-save></button></div>
      </form>
    </dialog>`;
  document.body.append(shared);
}

function applyLocale(locale) {
  const next = locale === "en" ? "en" : "es";
  document.documentElement.lang = next;
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const value = waikaText(element.dataset.i18n, next);
    if (value !== element.dataset.i18n) element.textContent = value;
  });
  document.querySelectorAll('a[href="/planes"]:not([data-i18n])').forEach((element) => {
    element.textContent = waikaText("nav.pricing", next);
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => {
    element.placeholder = waikaText(element.dataset.i18nPlaceholder, next);
  });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => {
    element.setAttribute("aria-label", waikaText(element.dataset.i18nAria, next));
  });
  document.querySelectorAll("[data-i18n-alt]").forEach((element) => {
    element.setAttribute("alt", waikaText(element.dataset.i18nAlt, next));
  });
  document.querySelectorAll("[data-es][data-en]").forEach((element) => {
    element.textContent = element.dataset[next];
  });
  const languageButton = document.querySelector("[data-language]");
  if (languageButton) {
    languageButton.textContent = next === "es" ? "EN" : "ES";
    languageButton.setAttribute("aria-label", waikaText("dock.language", next));
  }
  const chatOpen = document.querySelector("[data-chat-open]");
  const chatClose = document.querySelector("[data-chat-close]");
  const backTop = document.querySelector("[data-back-top]");
  if (chatOpen) chatOpen.setAttribute("aria-label", waikaText("dock.chat", next));
  if (chatClose) chatClose.setAttribute("aria-label", waikaText("chat.close", next));
  if (backTop) backTop.setAttribute("aria-label", waikaText("dock.top", next));
  const chatTitle = document.getElementById("chat-title");
  const chatIntro = document.querySelector("[data-chat-intro]");
  const chatInput = document.getElementById("chat-input");
  const chatSubmit = document.querySelector("[data-chat-form] button[type=submit]");
  if (chatTitle) chatTitle.textContent = waikaText("chat.title", next);
  if (chatIntro) chatIntro.textContent = waikaText("chat.intro", next);
  if (chatInput) chatInput.placeholder = waikaText("chat.placeholder", next);
  if (chatSubmit && !chatSubmit.disabled) chatSubmit.textContent = waikaText("chat.send", next);
  const cookieSet = {
    "[data-cookie-message]": "cookie.message", "[data-cookie-reject]": "cookie.reject", "[data-cookie-accept]": "cookie.accept",
    "[data-cookie-settings]": "cookie.settings", "#cookie-title": "cookie.title", "#cookie-dialog-title": "cookie.preferences",
    "[data-cookie-necessary-label]": "cookie.necessary", "[data-cookie-necessary-help]": "cookie.necessaryHelp",
    "[data-cookie-analytics-label]": "cookie.analytics", "[data-cookie-analytics-help]": "cookie.analyticsHelp",
    "[data-cookie-marketing-label]": "cookie.marketing", "[data-cookie-marketing-help]": "cookie.marketingHelp",
    "[data-cookie-save]": "cookie.save", "[data-cookie-cancel]": "cookie.cancel", "[data-cookie-only-necessary]": "cookie.onlyNecessary"
  };
  Object.entries(cookieSet).forEach(([selector, key]) => {
    const element = document.querySelector(selector);
    if (element) element.textContent = waikaText(key, next);
  });
  window.waikaLocale = next;
  document.dispatchEvent(new CustomEvent("waika:locale-change", { detail: { locale: next } }));
}

function initLanguage() {
  let saved = "es";
  try { saved = localStorage.getItem("waika-locale") || "es"; } catch {}
  applyLocale(saved);
  document.querySelector("[data-language]")?.addEventListener("click", () => {
    const next = document.documentElement.lang === "es" ? "en" : "es";
    try { localStorage.setItem("waika-locale", next); } catch {}
    applyLocale(next);
  });
  window.waikaTranslate = waikaText;
}

function initCookies() {
  const banner = document.querySelector(".cookie-banner");
  const dialog = document.querySelector(".cookie-dialog");
  const analytics = document.querySelector("[data-cookie-analytics]");
  const marketing = document.querySelector("[data-cookie-marketing]");
  if (!banner) return;
  const updateBannerLayout = () => {
    const visible = !banner.hidden;
    document.body.classList.toggle("cookie-banner-visible", visible);
    if (visible) {
      document.documentElement.style.setProperty("--cookie-banner-height", `${Math.ceil(banner.getBoundingClientRect().height)}px`);
    } else {
      document.documentElement.style.removeProperty("--cookie-banner-height");
    }
  };
  const read = () => {
    try { return JSON.parse(localStorage.getItem("waika-consent-v1") || "null"); } catch { return null; }
  };
  const store = (values) => {
    const decision = { necessary: true, analytics: Boolean(values.analytics), marketing: Boolean(values.marketing), savedAt: new Date().toISOString() };
    try { localStorage.setItem("waika-consent-v1", JSON.stringify(decision)); } catch {}
    banner.hidden = true;
    updateBannerLayout();
    document.dispatchEvent(new CustomEvent("waika:consent-change", { detail: decision }));
  };
  const openSettings = () => {
    const saved = read();
    analytics.checked = saved?.analytics === true;
    marketing.checked = saved?.marketing === true;
    dialog.showModal();
  };
  const currentConsent = read();
  banner.hidden = Boolean(currentConsent && currentConsent.necessary === true && typeof currentConsent.analytics === "boolean" && typeof currentConsent.marketing === "boolean");
  updateBannerLayout();
  if (window.ResizeObserver) new ResizeObserver(updateBannerLayout).observe(banner);
  window.addEventListener("resize", updateBannerLayout, { passive: true });
  document.querySelector("[data-cookie-accept]")?.addEventListener("click", () => store({ analytics: true, marketing: true }));
  document.querySelector("[data-cookie-reject]")?.addEventListener("click", () => store({}));
  document.querySelector("[data-cookie-open]")?.addEventListener("click", openSettings);
  document.querySelector("[data-cookie-settings]")?.addEventListener("click", openSettings);
  document.querySelector("[data-cookie-only-necessary]")?.addEventListener("click", () => { store({}); dialog.close(); });
  document.querySelector("[data-cookie-cancel]")?.addEventListener("click", () => dialog.close());
  document.querySelector("[data-cookie-save]")?.addEventListener("click", () => {
    store({ analytics: analytics.checked, marketing: marketing.checked });
    dialog.close();
  });
  dialog?.addEventListener("click", (event) => { if (event.target === dialog) dialog.close(); });
}

function initChat() {
  const panel = document.querySelector(".chat-panel");
  const messagesElement = document.querySelector(".chat-messages");
  const form = document.querySelector("[data-chat-form]");
  const input = document.getElementById("chat-input");
  const submit = form?.querySelector("button[type=submit]");
  if (!panel || !form || !input || !submit) return;
  const messages = [];
  const addMessage = (text, role = "assistant", isError = false) => {
    const bubble = document.createElement("p");
    bubble.className = `chat-message${role === "user" ? " user" : ""}${isError ? " error" : ""}`;
    bubble.textContent = text;
    messagesElement.append(bubble);
    messagesElement.scrollTop = messagesElement.scrollHeight;
    return bubble;
  };
  document.querySelector("[data-chat-intro]").textContent = waikaText("chat.intro");
  const open = () => {
    panel.hidden = false;
    panel.classList.add("is-open");
    document.body.classList.add("chat-open");
    document.querySelector("[data-chat-open]")?.setAttribute("aria-expanded", "true");
    input.focus();
  };
  const close = () => {
    panel.classList.remove("is-open");
    panel.hidden = true;
    document.body.classList.remove("chat-open");
    document.querySelector("[data-chat-open]")?.setAttribute("aria-expanded", "false");
    document.querySelector("[data-chat-open]")?.focus();
  };
  document.querySelector("[data-chat-open]")?.addEventListener("click", open);
  document.querySelector("[data-chat-close]")?.addEventListener("click", close);
  document.addEventListener("keydown", (event) => { if (event.key === "Escape" && !panel.hidden) close(); });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const content = input.value.trim();
    if (!content || submit.disabled) return;
    input.value = "";
    addMessage(content, "user");
    messages.push({ role: "user", content });
    submit.disabled = true;
    submit.textContent = waikaText("chat.busy");
    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ locale: document.documentElement.lang, messages: messages.slice(-10) }),
        signal: AbortSignal.timeout(18_000)
      });
      const result = await response.json();
      if (!response.ok || !result.success) throw new Error(result.message || waikaText("chat.error"));
      messages.push({ role: "assistant", content: result.answer });
      addMessage(result.answer);
    } catch (error) {
      addMessage(error.message || waikaText("chat.error"), "assistant", true);
    } finally {
      submit.disabled = false;
      submit.textContent = waikaText("chat.send");
      input.focus();
    }
  });
}

function initDock() {
  const dock = document.querySelector(".site-dock");
  const update = () => dock?.classList.toggle("is-scrolled", window.scrollY > 300);
  window.addEventListener("scroll", update, { passive: true });
  update();
  document.querySelector("[data-back-top]")?.addEventListener("click", () => {
    window.scrollTo({ top: 0, behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
  });
}

addSharedControls();
initLanguage();
initCookies();
initChat();
initDock();
